import{_ as l,c as o,o as r,ag as i}from"./chunks/framework.B-XtCDNB.js";const P=JSON.parse('{"title":"应用层（Application Layer）","description":"","frontmatter":{},"headers":[],"relativePath":"network/application-layer.md","filePath":"network/application-layer.md","lastUpdated":1759824077000}'),n={name:"network/application-layer.md"};function e(s,t,a,T,g,d){return r(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="应用层-application-layer" tabindex="-1">应用层（Application Layer） <a class="header-anchor" href="#应用层-application-layer" aria-label="Permalink to &quot;应用层（Application Layer）&quot;">​</a></h1><p>应用层是网络体系结构的<strong>最顶层</strong>，负责为用户提供网络服务，并处理用户和应用程序之间的交互。</p><h2 id="http" tabindex="-1">HTTP <a class="header-anchor" href="#http" aria-label="Permalink to &quot;HTTP&quot;">​</a></h2><p>HTTP（超文本传输协议）是一种用于在 Web 浏览器和 Web 服务器之间传输数据的应用层协议。它是建立在 TCP/IP 协议之上的，基于客户端 - 服务器模型。</p><p>HTTP 工作流程如下：</p><ol><li><strong>建立连接</strong>：客户端通过 <strong>TCP 三次握手</strong> 与服务器建立连接（默认 80 端口）。</li><li><strong>发送请求</strong>：客户端向服务器发送 HTTP 请求，包括请求行、请求头和请求体。</li><li><strong>处理请求</strong>：服务器接收到请求后，解析请求，执行相应的处理逻辑（获取资源、处理数据等）。</li><li><strong>发送响应</strong>：服务器将处理结果封装成 HTTP 响应（响应状态码（200/404 等）、响应头、响应体（HTML/JSON 等））发送回客户端。</li><li><strong>关闭连接</strong>：HTTP/1.0 默认关闭，HTTP/1.1 支持持久连接复用。</li></ol><h2 id="http-2" tabindex="-1">HTTP/2 <a class="header-anchor" href="#http-2" aria-label="Permalink to &quot;HTTP/2&quot;">​</a></h2><p>HTTP/2 是 HTTP 协议的第二个主要版本，于 2015 年作为 RFC 7540 发布。HTTP/2 的设计基于 Google 的 SPDY 协议，并在此基础上进行了扩展和标准化。</p><p>HTTP/2 的一些重要特性和改进：</p><ol><li><strong>多路复用（Multiplexing）</strong>：允许客户端在单个连接上同时发送多个请求。</li><li><strong>头部压缩（Header Compression）</strong>：使用 HPACK 算法对 HTTP 头部进行压缩，减少了请求和响应中传输的头部大小。</li><li><strong>服务器推送（Server Push）</strong>：允许服务器在客户端请求之前将资源推送给客户端，减少了客户端的等待时间。</li><li><strong>流量控制（Flow Control）</strong>：允许客户端和服务器在传输数据时进行流量控制，以防止过载和拥塞。</li><li><strong>服务器端请求优先级（Prioritization）</strong>：支持将请求划分为多个优先级，客户端可以指定请求的优先级，服务器可以根据优先级调整资源的传输顺序。</li><li><strong>二进制协议（Binary Protocol）</strong>：HTTP/2 将 HTTP 消息封装为二进制帧进行传输。</li></ol><h2 id="http-1-和-http-2-的区别" tabindex="-1">HTTP/1 和 HTTP/2 的区别 <a class="header-anchor" href="#http-1-和-http-2-的区别" aria-label="Permalink to &quot;HTTP/1 和 HTTP/2 的区别&quot;">​</a></h2><ol><li><p><strong>多路复用（Multiplexing）</strong></p><ul><li>HTTP/1：基于文本的协议，使用串行方式发送请求，每个请求都需要等待前一个请求的响应返回后才能发送下一个请求。</li><li>HTTP/2：引入了多路复用机制，可以在单个连接上同时发送多个请求和响应，消除了HTTP/1中的串行请求限制，提高了资源的加载速度。</li></ul></li><li><p><strong>头部压缩（Header Compression）</strong></p><ul><li>HTTP/1：每个请求和响应都会携带一系列的 HTTP 头部信息，这些头部信息在每次请求和响应时都会被发送，导致了不必要的重复传输。</li><li>HTTP/2：引入了头部压缩机制，使用 HPACK 算法对 HTTP 头部进行压缩，减少了传输的头部大小，降低了网络流量和延迟。</li></ul></li><li><p><strong>服务器推送（Server Push）</strong></p><ul><li>HTTP/1：客户端需要在收到 HTML 响应后解析 HTML 文档，发现其中需要的资源后再发送额外的请求获取这些资源。</li><li>HTTP/2：服务器可以在客户端请求之前将相关资源推送给客户端，减少了客户端的等待时间，提高了页面加载速度。</li></ul></li><li><p><strong>流量控制（Flow Control）</strong></p><ul><li>HTTP/1：基于 TCP 的流量控制机制，但缺乏对 HTTP 层面的流量控制。</li><li>HTTP/2：引入了自身的流量控制机制，允许客户端和服务器在传输数据时进行流量控制，以防止过载和拥塞。</li></ul></li><li><p><strong>服务器端请求优先级（Prioritization）</strong></p><ul><li>HTTP/1：不支持对请求的优先级进行明确控制，导致可能出现低优先级请求阻塞高优先级请求的情况。</li><li>HTTP/2：支持将请求划分为多个优先级，服务器可以根据优先级调整资源的传输顺序，优化页面的加载顺序，提高性能。</li></ul></li><li><p><strong>二进制协议（Binary Protocol）</strong></p><ul><li>HTTP/1：基于文本的协议，使用可读性较强的 ASCII 字符进行通信。</li><li>HTTP/2：将 HTTP 消息封装为二进制帧进行传输，更高效地进行了编码和解析，提高了传输效率。</li></ul></li></ol><table tabindex="0"><thead><tr><th><strong>特性</strong></th><th><strong>HTTP/1</strong></th><th><strong>HTTP/2</strong></th></tr></thead><tbody><tr><td><strong>传输方式</strong></td><td>文本协议，串行请求</td><td>二进制协议，多路复用</td></tr><tr><td><strong>头部处理</strong></td><td>无压缩，重复传输</td><td>HPACK 压缩，减少头部大小</td></tr><tr><td><strong>服务器推送</strong></td><td>不支持</td><td>可主动推送资源</td></tr><tr><td><strong>优先级控制</strong></td><td>无</td><td>支持请求优先级调度</td></tr></tbody></table><h2 id="https" tabindex="-1">HTTPS <a class="header-anchor" href="#https" aria-label="Permalink to &quot;HTTPS&quot;">​</a></h2><p>HTTPS 代表<strong>超文本传输安全协议</strong>（Hypertext Transfer Protocol Secure），是 HTTP 的安全版本。它通过使用 SSL（安全套接层）或 TLS（传输层安全）协议对通信数据进行加密和身份验证，以确保数据在客户端和服务器之间的安全传输。</p><ul><li><strong>作用</strong>：HTTP + SSL/TLS 加密，防窃听/篡改</li><li><strong>流程</strong>： <ol><li>客户端请求 → 服务器返回证书（含公钥）</li><li>双方协商生成<strong>对称加密密钥</strong>（主密钥）</li><li>后续通信使用对称加密传输数据</li></ol></li><li><strong>端口</strong>：443（HTTP 为 80）</li><li><strong>证书</strong>：由可信的第三方证书颁发机构（CA）签发，验证服务器身份</li></ul><h2 id="http-和-https-的区别" tabindex="-1">HTTP 和 HTTPS 的区别 <a class="header-anchor" href="#http-和-https-的区别" aria-label="Permalink to &quot;HTTP 和 HTTPS 的区别&quot;">​</a></h2><ol><li><p><strong>安全性</strong>：</p><ul><li>HTTP：是一种明文传输协议，数据在传输过程中不进行加密，容易受到窃听、篡改和偷窥等安全威胁。</li><li>HTTPS：通过使用 SSL（安全套接层）或 TLS（传输层安全）协议对通信数据进行加密，确保数据在客户端和服务器之间的安全传输，防止中间人攻击和数据泄露。</li></ul></li><li><p><strong>数据传输方式</strong>：</p><ul><li>HTTP：使用 TCP（传输控制协议）作为传输层协议，数据以明文形式传输。</li><li>HTTPS：同样使用 TCP 作为传输层协议，但通过 SSL/TLS 对数据进行加密和解密，保证数据的机密性和完整性。</li></ul></li><li><p><strong>默认端口</strong>：</p><ul><li>HTTP：默认端口为 80。</li><li>HTTPS：默认端口为 443。</li></ul></li><li><p><strong>证书要求</strong>：</p><ul><li>HTTP：不需要使用数字证书。</li><li>HTTPS：服务器必须拥有有效的数字证书，证明其身份。数字证书通常由可信的第三方证书颁发机构（CA）签发，用于验证服务器的身份，确保连接的安全性。</li></ul></li></ol><h2 id="websocket" tabindex="-1">WebSocket <a class="header-anchor" href="#websocket" aria-label="Permalink to &quot;WebSocket&quot;">​</a></h2><p>WebSocket 协议是一种在单个 TCP 连接上进行全双工通信的协议，允许客户端和服务器之间进行实时的双向数据传输。</p><p>主要特点：</p><ol><li><strong>全双工通信</strong>：允许客户端和服务器之间建立持久连接，双方可以同时进行数据的发送和接收。</li><li><strong>基于事件驱动</strong>：客户端和服务器可以通过事件来发送和接收数据。</li><li><strong>减少开销</strong>：WebSocket 协议通过在 HTTP 握手阶段升级协议，将 HTTP 连接升级为 WebSocket 连接，从而减少了握手和头部的开销，提高了通信的效率。</li><li><strong>与 Web 原生集成</strong>：WebSocket 协议与 Web 原生技术（如 HTML5）集成良好，可以在 Web 浏览器中直接使用 JavaScript 等客户端语言进行 WebSocket 通信，实现实时的数据传输。</li><li><strong>支持跨域通信</strong>：由于 WebSocket 协议在 HTTP 协议之上进行握手，因此它继承了 HTTP 的安全特性，包括同源策略、跨域通信等。</li></ol><p>工作原理：</p><ol><li><p><strong>握手阶段</strong>：</p><ul><li>客户端发起 HTTP 请求，请求升级为 WebSocket 协议。</li><li>服务器接受请求，返回 HTTP 101 状态码表示升级成功，此时连接转换为 WebSocket 连接。</li></ul></li><li><p><strong>数据传输</strong>：</p><ul><li>客户端和服务器可以通过 WebSocket 连接发送和接收数据帧（Frame）。</li><li>数据帧可以是文本帧、二进制帧或控制帧，用于传输各种类型的数据。</li></ul></li><li><p><strong>保持连接</strong>：</p><ul><li>WebSocket 连接是持久连接，通常保持连接打开，直到客户端或服务器明确关闭连接。</li></ul></li></ol><p>WebSocket 协议在实时通信和 Web 应用中得到广泛应用，特别是对于需要实时更新和交互的应用，如在线游戏、聊天应用、实时监控等场景，WebSocket 能够提供更加高效和即时的数据传输方式。</p><h2 id="websocket-和-http-的区别" tabindex="-1">WebSocket 和 HTTP 的区别 <a class="header-anchor" href="#websocket-和-http-的区别" aria-label="Permalink to &quot;WebSocket 和 HTTP 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>对比项</strong></th><th><strong>HTTP</strong></th><th><strong>WebSocket</strong></th></tr></thead><tbody><tr><td><strong>通信模式</strong></td><td>请求 - 响应（短连接）</td><td>全双工（长连接）</td></tr><tr><td><strong>头部开销</strong></td><td>每次请求带完整头部</td><td>仅握手阶段有 HTTP 头部</td></tr><tr><td><strong>数据格式</strong></td><td>文本</td><td>文本和二进制，允许传输各种类型的数据</td></tr><tr><td><strong>适用场景</strong></td><td>静态资源加载、表单提交</td><td>实时聊天、游戏、数据推送</td></tr></tbody></table><h2 id="ftp" tabindex="-1">FTP <a class="header-anchor" href="#ftp" aria-label="Permalink to &quot;FTP&quot;">​</a></h2><p>FTP（File Transfer Protocol，文件传输协议）是一种用于在网络上进行文件传输的协议。它允许用户在客户端和服务器之间传输文件，并提供了一套用于文件管理的指令。FTP 协议使用客户端 - 服务器模型，客户端发起连接并发送命令，服务器接收并响应这些命令，以实现文件的上传、下载、删除、重命名等操作。</p><p>FTP 协议的工作原理：</p><ol><li><strong>建立连接</strong>：客户端向服务器发起 TCP 连接请求，通常使用默认端口 21。</li><li><strong>用户认证</strong>：客户端在连接建立后，需要提供用户名和密码进行身份验证，以便服务器确认客户端的身份。</li><li><strong>文件传输</strong>：一旦认证成功，客户端可以发送 FTP 命令来管理文件。</li><li><strong>断开连接</strong>：文件传输完成后，客户端可以发送 <code>QUIT</code> 命令来关闭 FTP 连接，释放资源。</li></ol><h2 id="dns" tabindex="-1">DNS <a class="header-anchor" href="#dns" aria-label="Permalink to &quot;DNS&quot;">​</a></h2><p>DNS（Domain Name System，域名系统）是互联网中用于将域名（例如 example.com）解析为 IP 地址（例如 192.0.2.1）的分布式命名系统。它充当了互联网中的“电话簿”，通过将易于记忆的域名映射到对应的 IP 地址，使用户可以方便地访问互联网上的各种资源。</p><p>DNS 的工作原理：</p><ol><li>用户在浏览器输入域名，浏览器向本地 DNS 解析器请求解析。</li><li>本地 DNS 先查缓存（浏览器缓存 → 本地 DNS 缓存），若无结果则向根域名服务器查询。</li><li>根域名服务器指向对应的顶级域名服务器（如 .com），本地 DNS 继续查询。</li><li>顶级域名服务器提供下一层域名服务器，直到获取最终 IP 地址。</li><li>本地 DNS 返回 IP，浏览器据此访问目标网站。</li></ol><h2 id="cdn" tabindex="-1">CDN <a class="header-anchor" href="#cdn" aria-label="Permalink to &quot;CDN&quot;">​</a></h2><p>CDN（Content Delivery Network，内容分发网络）是一组分布在全球不同位置的服务器集群，用于提供高效的内容传递服务。CDN 的目标是将内容（如网页、图片、视频、音频等）快速、可靠地分发给用户，以提高网站的性能、可用性和安全性。</p><p>CDN 的工作原理：</p><ol><li><strong>内容缓存</strong>：CDN 在全球服务器上缓存网站内容，用户请求时从最近的节点获取数据。</li><li><strong>请求路由</strong>：用户的请求被智能路由到最近的 CDN 服务器，而非直接访问原始服务器。</li><li><strong>内容传输</strong>：CDN 服务器快速响应并优化传输，提高加载速度和网站性能。</li><li><strong>负载分担</strong>：CDN 分散访问流量，减少原始服务器压力，提升网站稳定性。</li><li><strong>安全防护</strong>：CDN 提供 DDoS 防护和 Web 防火墙，增强网站安全性。</li></ol><ul><li><strong>加速原理</strong>：全球节点缓存资源，用户就近访问</li><li><strong>关键功能</strong>： <ul><li>缓存静态资源（HTML/CSS/图片）</li><li>负载均衡 + 动态内容优化</li><li>DDoS 防护 + 压缩传输</li></ul></li></ul><h2 id="post-和-get-的区别" tabindex="-1">POST 和 GET 的区别 <a class="header-anchor" href="#post-和-get-的区别" aria-label="Permalink to &quot;POST 和 GET 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>区别</strong></th><th><strong>GET</strong></th><th><strong>POST</strong></th></tr></thead><tbody><tr><td><strong>数据传输方式</strong></td><td>通过 URL 查询字符串传输，数据附加在 URL 末尾</td><td>通过 HTTP 请求消息体传输，数据不会出现在 URL 中</td></tr><tr><td><strong>安全性</strong></td><td>数据暴露在 URL 上，不适合传输敏感信息</td><td>数据在消息体中，相对更安全，适合传输敏感信息</td></tr><tr><td><strong>缓存</strong></td><td>可以被浏览器缓存，适用于获取静态资源</td><td>默认不会被缓存，每次请求都会重新提交</td></tr><tr><td><strong>参数长度限制</strong></td><td>受 URL 长度限制（通常几千字符）</td><td>不受 URL 长度限制，可传输大量数据</td></tr><tr><td><strong>幂等性</strong></td><td>通常是幂等的，多次请求结果相同</td><td>通常非幂等的，多次请求可能产生不同的结果</td></tr></tbody></table><h2 id="options-请求" tabindex="-1">OPTIONS 请求 <a class="header-anchor" href="#options-请求" aria-label="Permalink to &quot;OPTIONS 请求&quot;">​</a></h2><p><strong>OPTIONS 请求</strong> 用于获取服务器支持的 HTTP 方法和相关的通信选项，主要作用如下：</p><ol><li><p><strong>查询服务器支持的 HTTP 方法</strong></p><ul><li>客户端可以使用 <code>OPTIONS</code> 请求来询问服务器某个资源（URL）支持哪些 HTTP 方法，例如 <code>GET</code>、<code>POST</code>、<code>PUT</code>、<code>DELETE</code> 等。</li></ul></li><li><p><strong>用于 CORS 预检请求（Preflight Request）</strong></p><ul><li>在跨域请求中，如果请求方法是 <code>PUT</code>、<code>DELETE</code> 或者包含特殊的 <code>Headers</code>，浏览器会先发送 <code>OPTIONS</code> 预检请求，以确认服务器是否允许该跨域请求。</li></ul></li><li><p>使用 <code>OPTIONS</code> 方法发送嗅探请求，以判断是否有对指定资源的访问权限。</p></li></ol><h2 id="浏览器地址栏输入-url-到页面渲染的整个流程" tabindex="-1">浏览器地址栏输入 URL 到页面渲染的整个流程 <a class="header-anchor" href="#浏览器地址栏输入-url-到页面渲染的整个流程" aria-label="Permalink to &quot;浏览器地址栏输入 URL 到页面渲染的整个流程&quot;">​</a></h2><ol><li><p><strong>URL 解析</strong>：浏览器会对该 URL 进行解析，分析需要使用的<strong>传输协议</strong>和<strong>请求资源的路径</strong>。</p></li><li><p><strong>缓存检查</strong>：检查本地缓存，如果存在缓存资源且未过期则直接使用，否则发起新请求。</p></li><li><p><strong>DNS 查询</strong>：浏览器通过 DNS 解析器查询该域名对应的 IP 地址。如果 DNS 缓存中存在该域名对应的 IP 地址，则直接返回；否则，将请求发送到 DNS 服务器进行解析。</p></li><li><p><strong>建立 TCP 连接</strong>：浏览器使用 HTTP 协议建立与服务器三次握手的 TCP 连接。在建立连接的过程中，如果是 HTTPS 协议，还需要进行 TLS/SSL 四次握手来确保通信安全。</p></li><li><p><strong>发起 HTTP 请求</strong>：浏览器向服务器发送 HTTP 请求。</p></li><li><p><strong>服务器处理请求</strong>：服务器接收到 HTTP 请求后，根据请求的 URL 和方法进行相应的处理。处理过程可能包括查询数据库、生成动态内容、读取静态文件等操作。</p></li><li><p><strong>服务器响应</strong>：服务器处理完请求后，将相应的结果以 HTTP 响应的形式返回给浏览器。</p></li><li><p><strong>接收响应</strong>：浏览器接收到服务器的响应后，开始解析响应。检查响应头中的 Content-Type，确定响应的数据类型（如 HTML、JSON、图片等），然后根据相应的数据类型进行相应的处理。</p></li><li><p><strong>页面渲染</strong>：如果响应的是 HTML 类型的数据，浏览器开始解析 HTML，并构建 DOM 树。在构建 DOM 树的过程中，遇到外部资源（如 CSS、JavaScript、图片等）的引用，则会发起额外的请求获取这些资源。同时，浏览器还会解析 CSS，构建 CSSOM 树，并将 DOM 树和 CSSOM 树合并成渲染树。最后，浏览器根据渲染树进行页面渲染，呈现给用户。</p></li><li><p><strong>断开连接</strong>：页面加载完成后，通过 TCP 四次挥手断开连接。</p></li></ol><h2 id="正向代理和反向代理" tabindex="-1">正向代理和反向代理 <a class="header-anchor" href="#正向代理和反向代理" aria-label="Permalink to &quot;正向代理和反向代理&quot;">​</a></h2><p>正向代理和反向代理是两种常见的网络代理服务器，用于在客户端和服务器之间进行通信。它们的主要区别在于代理服务器的角色和通信方向。</p><ol><li><strong>正向代理（Forward Proxy）</strong>： <ul><li>客户端视角：代理服务器代替客户端向服务器发送请求。</li><li>用途： <ul><li>访问受限的服务器：通过代理服务器绕过服务器的访问限制。</li><li>隐私保护：代理服务器可以隐藏客户端的真实 IP 地址。</li><li>缓存：代理服务器可以缓存请求的响应，提高访问速度。</li></ul></li><li>示例：VPN、代理服务器软件。</li></ul></li><li><strong>反向代理（Reverse Proxy）</strong>： <ul><li>服务器视角：代理服务器代替服务器接收请求并转发给客户端。</li><li>用途： <ul><li>负载均衡：将请求分发到多个服务器，实现负载均衡。</li><li>隐藏服务器：代理服务器可以隐藏服务器的真实 IP 地址。</li><li>安全防护：代理服务器可以对请求进行过滤和安全防护。</li></ul></li><li>示例：Nginx、Apache 等 Web 服务器。</li></ul></li></ol><h2 id="负载平衡的实现方式" tabindex="-1">负载平衡的实现方式 <a class="header-anchor" href="#负载平衡的实现方式" aria-label="Permalink to &quot;负载平衡的实现方式&quot;">​</a></h2><p>负载平衡是一种通过<strong>分配请求到多个服务器来均衡服务器负载</strong>的方法，以提高系统的性能、可靠性和可扩展性。</p><p>常见方案：</p><ol><li><strong>硬件</strong>：F5（高性能，成本高）</li><li><strong>软件</strong>：Nginx（轮询/加权/最少连接）</li><li><strong>DNS 轮询</strong>：多个 IP 解析，简单但无动态调度</li><li><strong>自动扩展</strong>：云服务动态扩容（如 AWS ELB）</li></ol><h2 id="多网站共享登录-单点登录-sso" tabindex="-1">多网站共享登录（单点登录 SSO） <a class="header-anchor" href="#多网站共享登录-单点登录-sso" aria-label="Permalink to &quot;多网站共享登录（单点登录 SSO）&quot;">​</a></h2><p>前端单点登录（SSO）的实现常采用如下思路：</p><ol><li><strong>中心认证服务器</strong>：所有系统通过一个统一的认证中心（如 OAuth2.0/OIDC 服务器）进行登录验证。</li><li><strong>登录重定向</strong>：用户访问任一系统时，如未登录则重定向到认证服务器进行登录。</li><li><strong>令牌（Token）机制</strong>：登录成功后，认证服务器生成令牌（如 JWT），并通过重定向或回调传递给前端。</li><li><strong>状态共享</strong>：前端存储令牌（如 cookie 或 localStorage），后续请求附带令牌进行身份验证，实现各系统共享登录状态。</li></ol>',57)])])}const h=l(n,[["render",e]]);export{P as __pageData,h as default};
